import{z as n,x as B,o as r,c as d,q as s,j as i,D as o,d as E,s as A,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"位运算技巧","description":"","frontmatter":{"title":"位运算技巧","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ae-bit-tricks.md","filePath":"cs/ae-bit-tricks.md","lastUpdated":1791063341000}'),p={name:"cs/ae-bit-tricks.md"};function c(m,a,D,h,x,u){const t=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=s('<h1 id="位运算技巧" tabindex="-1">位运算技巧 <a class="header-anchor" href="#位运算技巧" aria-label="Permalink to &quot;位运算技巧&quot;">​</a></h1><div class="epigraph"><p>一个机器字是 $w$ 个并行的比特处理器；把状态压进字里，指令数才配得上字宽。</p><footer>—— 据 Knuth, The Art of Computer Programming, Vol. 4A；Warren, Hacker&#39;s Delight, 2002 整理</footer></div><p><a href="/cs/ae-cache-friendly">上一课</a>把字节摆近了，本课钻进字内部。主干课的<a href="/cs/word-ram">word RAM 与位并行</a>已经证明字宽可以是理论资产：一次处理 \\(w\\) 比特，比较模型的下界都被撬动。本课收工程上最常用的那批字内技巧——置位清位、取低位、子集枚举、无分支化——以及它们赖以成立的补码与移位语义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一批高频小操作，朴素写法全是循环与分支：数一个字里有几个 1，逐位右移 \\(w\\) 次；找最低位的 1，先判零再移；取两数较小者，一个比较分支；枚举集合的子集，逐个加一再筛位数。缺口：这些操作全部可以在常数条字指令内完成，而它们常出现在最热的循环里——压缩、棋类走法生成、哈希与图算法的位集。不这么做会错在两处：不查语义就上手，有符号左移与超宽移位是未定义行为，可移植性碎掉；或者为炫技全套位运算化，reviewer 读不懂，正确性无从把守。</p><p><span class="marginnote">术语翻译：lowbit（<code>x &amp; (-x)</code>）就是用「原码与补码按位与」的手段来做「把最低位那个 1 单独抠出来」的事——比如 \\(x=44\\)（二进制 <code>101100</code>），lowbit 就是 <code>000100</code>（即 4），其余位全被清掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清最低位的 1 用 <code>x &amp; (x-1)</code>：借位恰好把最低的 1 及其右侧归零。数 1 的个数（popcount）因此可写成「循环执行 \\(x\\ \\&amp;=\\ x-1\\)，次数即 1 的个数」；硬件更直接，x86 有 POPCNT，AArch64 有 CNT 与 CLZ（见<a href="/cs/aarch64-isa">ARM AArch64</a>），工程上优先内建指令。</p><p>取最低位的 1 用 <code>x &amp; (-x)</code>（lowbit），它是补码等式 \\(-x=\\bar{x}+1\\) 的直接推论。由它派生子集枚举：Gosper&#39;s hack 从一个 popcount 为 \\(k\\) 的字直接跳到下一个同为 \\(k\\) 位 1 的字，枚举 \\(n\\) 元集合的全部 \\(k\\) 元子集只需 \\(\\binom{n}{k}\\) 步而非 \\(2^n\\) 步筛。</p><p>定位最低 1 的位置：把 lowbit 孤立后用 de Bruijn 乘法映射到查表下标，或直接用 CTZ/CLZ 指令。无分支化：min、max、abs 写成掩码算术，消掉数据依赖分支——接上一课的账，省的不是指令条数而是误预测。</p>',10)),(r(),i(l,null,{default:o(()=>[A(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SET%5B%22%E9%9B%86%E5%90%88%E7%8A%B6%E6%80%81%EF%BC%9A%E6%AF%8F%E5%85%83%E7%B4%A0%E4%B8%80%E6%AF%94%E7%89%B9%22%5D%20--%3E%20WORD%5B%22%E5%8E%8B%E8%BF%9B%E6%9C%BA%E5%99%A8%E5%AD%97%22%5D%0A%20%20WORD%20--%3E%20OPS%5B%22%E5%AD%97%E5%86%85%E5%B9%B6%E8%A1%8C%EF%BC%9AAND%20%2F%20OR%20%2F%20XOR%20%E4%B8%80%E6%9D%A1%E6%8C%87%E4%BB%A4%22%5D%0A%20%20OPS%20--%3E%20BR%5B%22%E6%97%A0%E5%88%86%E6%94%AF%E5%8C%96%EF%BC%9A%E6%8E%A9%E7%A0%81%E6%9B%BF%E4%BB%A3%E6%AF%94%E8%BE%83%E8%B7%B3%E8%BD%AC%22%5D%0A%20%20BR%20--%3E%20WIN%5B%22%E6%8C%87%E4%BB%A4%E6%95%B0%E4%B8%8E%E8%AF%AF%E9%A2%84%E6%B5%8B%E5%90%8C%E6%97%B6%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"为什么有效：一条字指令同时处理 \\(w\\) 比特，位技巧把「按元素循环」折叠成「字内并行」——这正是 word RAM 模型的工程面，也解释了为什么棋类 AI 把整盘 64 格压成一个 64 位字后，走法生成变成几条 AND 与移位的表达式。补码为什么撑得起 lowbit：\\(\\bar{x}+1\\) 恰好把 \\(x\\) 最低 1 以下的所有位变回原样，于是在最低 1 的位置上两者同为一，其余位上互补，按位与只留下它。无分支为什么快：分支的代价不在比较指令本身，而在预测错误的十几周期罚金；掩码路径没有预测可言，延迟恒定，对随机输入尤其值钱。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},[E("Gosper's hack 两行："),e("code",null,"c = s & -s; r = s + c; s' = (((r ^ s) >> 2) / c) | r"),E("。它出自 HAKMEM（MIT AI Memo 239, 1972）第 175 项；注意推导在 \\(c=0\\)（空集）时无意义，调用前必须先判空——位技巧的 bug 常藏在边界，不在主干。")])],-1)),a[6]||(a[6]=e("p",null,[E("方法一节的图回答「位并行为什么赢」，下面这张回答另一个问题："),e("code",null,"x & (x-1)"),E(" 到底怎样恰好清掉最低位的 1，popcount 循环为何因此正确。")],-1)),(r(),i(l,null,{default:o(()=>[A(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22x%20%3D%200b101100%20(%E5%8D%81%E8%BF%9B%E5%88%B6%2044)%22%5D%20--%3E%20M%5B%22x-1%20%3D%200b101011%3A%20%E5%80%9F%E4%BD%8D%E6%8A%8A%E6%9C%80%E4%BD%8E%201%20%E5%8F%98%200%2C%20%E5%85%B6%E5%8F%B3%E4%BE%A7%E5%85%A8%E5%8F%98%201%22%5D%0A%20%20M%20--%3E%20AND%5B%22%E6%8C%89%E4%BD%8D%E4%B8%8E%3A%200b101100%20%26%200b101011%22%5D%0A%20%20AND%20--%3E%20R%5B%22%E5%BE%97%200b101000%3A%20%E6%81%B0%E5%A5%BD%E5%8F%AA%E5%B0%91%E4%BA%86%E4%B8%80%E4%B8%AA%201%22%5D%0A%20%20R%20--%3E%20LOOP%7B%22x%20%E8%BF%98%E9%9D%9E%E9%9B%B6%E5%90%97%3F%22%7D%0A%20%20LOOP%20--%20%22%E6%98%AF%22%20--%3E%20CNT%5B%22%E8%AE%A1%E6%95%B0%E5%8A%A0%E4%B8%80%2C%20%E5%86%8D%E6%B8%85%E4%B8%80%E6%AC%A1%22%5D%0A%20%20CNT%20--%3E%20LOOP%0A%20%20LOOP%20--%20%22%E5%90%A6%22%20--%3E%20DONE%5B%22%E5%BE%AA%E7%8E%AF%E6%AC%A1%E6%95%B0%20%3D%201%20%E7%9A%84%E4%B8%AA%E6%95%B0%20%3D%203%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">数字实例：从 64 个元素里枚举全部 8 元子集——逐个加一再筛位数要碰 \\(2^{64}\\approx 1.8\\times 10^{19}\\) 个字；Gosper&#39;s hack 只在 \\(\\binom{64}{8}\\approx 4.4\\times 10^9\\) 个合法子集之间跳跃，差约十的十次方倍，这正是「跳」而不是「筛」的价值。</span></p><p><span class="marginnote">常见误区：初学者容易以为「无分支一定更快」——当分支几乎总走同一边（高度可预测）时，普通写法只付一次比较的钱，掩码算术反而多条指令；无分支的红利只在分支方向随机、误预测频繁的热循环里兑现。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>语义先于速度：有符号数左移、移位计数超字长，在 C/C++ 里是未定义或实现定义行为，位技巧默认用无符号类型并把移位量约束在字宽内。编译器已认得一部分模式，popcount 与低位定位优先内建与标准函数，手写只在没有对应指令的旧平台上划算。位并行按「一个字一打包」工作，宽度到顶之后再加宽的是 SIMD 的通道并行，见<a href="/cs/par-simd-vectorization">SIMD 与向量化</a>；那是另一套语义，不要混写。可读性预算同前两课：每处位运算配一行「它是谁」的注释，测试钉住 0、全 1、最高位三个边界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>位技巧的本质是字内并行：一条指令处理 \\(w\\) 比特，word RAM 的工程兑现。</li><li>三件套：<code>x&amp;(x-1)</code> 清低位、<code>x&amp;(-x)</code> 取 lowbit、Gosper&#39;s hack 跳下一个同位数子集；有硬件指令（POPCNT/CLZ）时直接用。</li><li>无分支化省的是误预测的方差，不是指令条数，对随机数据尤其值钱。</li><li>语义先于速度：无符号类型、移位边界、空集特判，否则未定义行为。</li><li>出处：Knuth, <em>TAOCP</em> Vol. 4A；Warren, <em>Hacker&#39;s Delight</em>, 2002；HAKMEM, MIT AI Memo 239, 1972。</li></ul>',6))])}const f=n(p,[["render",c]]);export{C as __pageData,f as default};
